// DO NOT EDIT THIS FILE.
// Write your code only in database-question.js.
// node index.js         runs database-question.js
// node index.js answer  runs database-answer.js

import express from "express";
import { fileURLToPath } from "node:url";

const useAnswer = process.argv[2] === "answer";
const {
  connectDB,
  getAllMembers,
  findMembersByPlan,
  findMembersByMinVisits,
  getTopThreeVisitors,
  addMember,
} = await import(useAnswer ? "./database-answer.js" : "./database-question.js");

if (useAnswer) {
  console.log("Using database-answer.js");
}

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database-question.js.`,
    });
  }
  res.json(data);
}

app.get("/api/members", async (req, res) => {
  try {
    sendList(res, await getAllMembers(), "getAllMembers");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/members/search", async (req, res) => {
  try {
    sendList(res, await findMembersByPlan(req.query.plan), "findMembersByPlan");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/members/filter", async (req, res) => {
  const minVisits = Number(req.query.minVisits);
  if (Number.isNaN(minVisits)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findMembersByMinVisits(minVisits), "findMembersByMinVisits");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/members/top", async (req, res) => {
  try {
    sendList(res, await getTopThreeVisitors(), "getTopThreeVisitors");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/members", async (req, res) => {
  try {
    const saved = await addMember(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addMember() did not return the saved member. Complete it in database-question.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
